use std :: collections :: { HashMap , HashSet } ; use std :: time :: Duration ; use chrono :: { DateTime , Utc } ; use derive_setters :: Setters ; use serde :: { Deserialize , Serialize } ; use uuid :: Uuid ; pub use crate :: file_operation :: FileOperation ; use crate :: { Todo , TodoItem , TodoStatus } ; use pretty_assertions :: assert_eq ; use super :: * ; use crate :: ToolKind ; impl Metrics { # [doc = " Records a file operation, replacing any previous operation for the same"] # [doc = " file. Only Read operations are tracked in files_accessed."] pub fn insert (mut self , path : String , metrics : FileOperation) -> Self { if metrics . tool == crate :: ToolKind :: Read { self . files_accessed . insert (path . clone ()) ; } self . file_operations . insert (path , metrics) ; self } # [doc = " Gets the session duration if tracking has started"] pub fn duration (& self , now : DateTime < Utc >) -> Option < Duration > { self . started_at . map (| start | (now - start) . to_std () . unwrap_or_default ()) } # [doc = " Returns todos currently in pending or in-progress states."] pub fn get_active_todos (& self) -> Vec < Todo > { self . todos . iter () . filter (| todo | matches ! (todo . status , TodoStatus :: Pending | TodoStatus :: InProgress)) . cloned () . collect () } # [doc = " Returns all known todos, including historical completed todos."] pub fn get_todos (& self) -> & [Todo] { & self . todos } # [doc = " Applies a list of todo changes using content as the matching key."] # [doc = ""] # [doc = " For each incoming item:"] # [doc = " - If `status` is `cancelled`: remove the matching item (if found)."] # [doc = " - If an item with the same content already exists: update its status."] # [doc = " - Otherwise: add a new item with a server-generated ID."] # [doc = ""] # [doc = " Completed items that are not mentioned in the incoming list are"] # [doc = " preserved in history. Active items (pending / in_progress) that are"] # [doc = " not mentioned remain unchanged."] # [doc = ""] # [doc = " Returns the list of currently active (pending / in_progress) todos."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " Returns an error if any todo content is empty or exceeds 1000"] # [doc = " characters."] pub fn apply_todo_changes (& mut self , changes : Vec < TodoItem >) -> anyhow :: Result < Vec < Todo > > { for item in & changes { if item . content . trim () . is_empty () { anyhow :: bail ! ("Todo content cannot be empty") ; } if item . content . len () > 1000 { anyhow :: bail ! ("Todo content exceeds maximum length of 1000 characters") ; } } for item in changes { if item . status == TodoStatus :: Cancelled { self . todos . retain (| t | t . content != item . content) ; } else if let Some (existing) = self . todos . iter_mut () . find (| t | t . content == item . content) { existing . status = item . status ; } else { self . todos . push (Todo { id : Uuid :: new_v4 () . to_string () , content : item . content , status : item . status , }) ; } } Ok (self . get_active_todos ()) } }